function<int(int)> compose(function<int(int)> f, function<int(int)> g) {
    return [f, g](int x) { return f(g(x)); };
}

auto double_it = [](int x) { return x * 2; };
auto increment = [](int x) { return x + 1; };
auto result = compose(double_it, increment)(5);
cout << result << endl;

function<int(int, int, int)> curry(function<int(int, int, int)> f) {
    return [f](int a) {
        return [f, a](int b) {
            return [f, a, b](int c) {
                return f(a, b, c);
            };
        };
    };
}

auto add3 = [](int a, int b, int c) { return a + b + c; };
auto curried = curry(add3);
cout << curried(1)(2)(3) << endl;

vector<int> flatten(const vector<vector<int>>& lists) {
    vector<int> result;
    for (const auto& list : lists) {
        result.insert(result.end(), list.begin(), list.end());
    }
    return result;
}

template<typename T>
vector<T> filter(function<bool(T)> pred, const vector<T>& vec) {
    vector<T> result;
    for (const auto& item : vec) {
        if (pred(item)) result.push_back(item);
    }
    return result;
}

auto isEven = [](int x) { return x % 2 == 0; };
auto evens = filter(isEven, vector<int>{1, 2, 3, 4, 5, 6});

template<typename T, typename R>
